    n, m = map(int, input_data[0].split())
    s, t = map(int, input_data[1].split())

    edges = []
    for i in range(m):
        parts = list(map(int, input_data[2 + i].split()))
        edges.append(parts)

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for i, (u, v, w) in enumerate(edges):
        adj[u].append((v, i + 1))
        adj[v].append((u, i + 1))

    def bfs_check(removed_edges):
        """Check if s can reach t without using edges in removed_edges"""
        visited = [False] * (n + 1)
        queue = deque([s])
        visited[s] = True

        while queue:
            curr = queue.popleft()
            if curr == t:
                return True

            for neighbor, edge_id in adj[curr]:
                if not visited[neighbor] and edge_id not in removed_edges:
                    visited[neighbor] = True
                    queue.append(neighbor)

        return visited[t]

    # Try removing 0 edges
    if not bfs_check(set()):
        return '0\n0\n'

    min_cost = float('inf')
    best_result = None

    # Try removing 1 edge
    for i in range(m):
        if bfs_check({i + 1}):
            continue
        cost = edges[i][2]
        if cost < min_cost:
            min_cost = cost
            best_result = ({i + 1},)

    if best_result is not None:
        return f'{min_cost}\n1\n{best_result[0][0]}'

    # Try removing 2 edges
    for i in range(m):
        for j in range(i, m):
            removed = {i + 1, j + 1}
            if bfs_check(removed):
                continue
            cost = edges[i][2] + edges[j][2]
            if cost < min_cost:
                min_cost = cost
                best_result = (i + 1, j + 1)

    if best_result is not None:
        road_str = f"{best_result[0]} {best_result[1]}"
        return f'{min_cost}\n2\n{road_str}'

