        dist[start] = 0
        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    queue.append(v)
        return dist

    # Compute all pairwise distances
    all_dist = {}
    for i in range(1, n + 1):
        dists = bfs_distances(i)
        for j in range(1, n + 1):
            all_dist[(i, j)] = dists[j]

    # Greedy strategy: sort nodes by depth and pair farthest available
    # Compute depth (distance from arbitrary root)
    def compute_depths():
        start = 1
        depth = {start: 0}
        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if v not in depth:
                    depth[v] = depth[u] + 1
                    queue.append(v)
        return depth

    depths = compute_depths()

    # Sort nodes by depth
    nodes_by_depth = sorted(range(1, n + 1), key=lambda x: depths[x])

    # Greedy: pick two furthest node pairs that can be swapped
    from itertools import permutations

    best_assignment = None
    best_score = -1

