    if n <= 10:
        from itertools import permutations
        for perm in permutations(range(1, n + 1)):
            valid = True
            score = 0
            for i in range(1, n + 1):
                if perm[i-1] == i:
                    valid = False
                    break
                score += all_dist[(i, perm[i-1])]
            if valid and score > best_score:
                best_score = score
                best_assignment = tuple(perm)
    else:
        # For larger N, use greedy with random restarts
        import random

        def score_assignment(perm):
            s = 0
            for i in range(1, n + 1):
                s += all_dist[(i, perm[i-1])]
            return s

        # Generate initial valid assignment using greedy
