            perm = [0] * n
            used = [False] * (n + 1)
            for i in range(n):
                node = nodes_by_depth[i]
                # Find destination not itself and not used
                candidates = [j for j in range(1, n + 1) if j != node and not used[j]]
                if not candidates:
                    return None
                best_dest = max(candidates, key=lambda x: all_dist[(node, x)])
                perm[i] = best_dest
                used[best_dest] = True
            return tuple(perm)

        # Generate random valid derangement
        def random_derangement():
