                    j = (i + 1 + random.randint(1, n - 2)) % n
                    perm[i+1], perm[j+1] = perm[j+1], perm[i+1]
            return tuple(perm.values())

        # Local search optimization
        assignments = [greedy_init()]
        for _ in range(min(10, n - 3)):
