def solution(input_str):
    data = input_str.split()
    idx = 0
    n = int(data[idx]); idx += 1
    m = int(data[idx]); idx += 1

    if m == n - 1:
        return ""

    edges = []

    for i in range(m):
        u = int(data[idx]); idx += 1
        v = int(data[idx]); idx += 1
        w = int(data[idx]); idx += 1
        edges.append((w, u - 1, v - 1, i))

    # Sort by weight for MST
    sorted_edges = sorted(edges, key=lambda x: x[0])

    # Build MST using Kruskal's
    parent = list(range(n))
    rank = [0] * n

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px == py:
            return False
        if rank[px] < rank[py]:
            px, py = py, px
        parent[py] = px
        if rank[px] == rank[py]:
            rank[px] += 1
        return True

    mst_adj = [[] for _ in range(n)]
    mst_indices = set()

    for w, u, v, orig_idx in sorted_edges:
        if union(u, v):
            mst_adj[u].append((v, w))
            mst_adj[v].append((u, w))
            mst_indices.add(orig_idx)

    # Build LCA structure using binary lifting
    MAX_LOG = 20
    up = [[-1] * n for _ in range(MAX_LOG)]
    path_max = [[0] * n for _ in range(MAX_LOG)]
    depth = [-1] * n

    stack = [(0, -1, 0, 0)]

    while stack:
        node, parent, d, edge_w = stack.pop()
        depth[node] = d
        up[0][node] = parent
        path_max[0][node] = edge_w

        for i in range(1, MAX_LOG):
            if up[i-1][node] != -1:
                up[i][node] = up[i-1][up[i-1][node]]
                path_max[i][node] = max(path_max[i-1][node], path_max[i-1][up[i-1][node]])

        for neighbor, weight in mst_adj[node]:
            if neighbor != parent:
                stack.append((neighbor, node, d + 1, weight))

    def query_path_max(u, v):
        if u == v:
            return 0

        if depth[u] < depth[v]:
            u, v = v, u

        res = 0
        diff = depth[u] - depth[v]

        for i in range(MAX_LOG):
            if diff & (1 << i):
                res = max(res, path_max[i][u])
                u = up[i][u]

        if u == v:
            return res

        for i in range(MAX_LOG - 1, -1, -1):
            if up[i][u] != up[i][v]:
                res = max(res, path_max[i][u])
                res = max(res, path_max[i][v])
                u = up[i][u]
                v = up[i][v]

        res = max(res, path_max[0][u], path_max[0][v])
        return res

    # Collect results for non-MST edges in original order
    results = [None] * m
    output = []

    for w, u, v, orig_idx in edges:
        if orig_idx not in mst_indices:
            max_weight = query_path_max(u, v)
            output.append(str(max_weight))

    return '\n'.join(output) + '\n'

