class Parser:
    def __init__(self, s):
        self.s = s
        self.pos = 0
        self.n = len(s)

    def peek(self):
        return self.s[self.pos] if self.pos < self.n else None

    def consume(self):
        if self.pos < self.n:
            c = self.s[self.pos]
            self.pos += 1
            return c
        return None

    def parse_expr(self):
        # expr ::= term | expr '+' term (left-recursive)
        result, length = self.parse_term()
        while self.peek() == '+':
            self.consume()  # consume '+'
            term_val, term_len = self.parse_term()
            # Concatenate: result * 10^term_len + term_val
            result = (result * pow(10, term_len, MOD) + term_val) % MOD
            length += term_len
        return result, length

    def parse_term(self):
        # term ::= number | number '-' number | number '(' expression ')'
        if self.peek() == '(':
            # Wrong! term doesn't start with '('
            # Actually term can be number '(' ext ')
            pass

        # First, parse the initial number
        initial_num = self.parse_number()

        if initial_num is None:
            # Shouldn't happen with valid input
            return 0, 0

        # Check if it's a range: number - number
        if self.peek() == '-':
            self.consume()  # consume '-'
            r_num, r_len = self.parse_number()
            if r_num is None:
                r_num = 0
                r_len = 0

            # Compute range [l, r]
            return self._compute_range(initial_num, r_num), r_len

        # Check if it's repetition: number ( expression )
        elif self.peek() == '(':
            self.consume()  # consume '('
            expr_result, expr_len = self.parse_expr()
            self.consume()  # consume ')'
            return self._compute_repeat(initial_num, expr_result, expr_len), expr_len

        # Otherwise, just a number
        else:
            return initial_num, len(str(initial_num))

    def parse_number(self):
        # number ::= pos_digit | number digit
        if self.peek() is None or not self.peek().isdigit():
            return None
        val = 0
        while self.peek() and self.peek().isdigit():
            val = val * 10 + int(self.consume())
        return val, len(str(val))

    def _compute_range(self, l, r):
        # Concatenate numbers l, l+1, ..., r
        result = 0
        digits = 0
        for i in range(l, r + 1):
            s = str(i)
            result = (result * pow(10, len(s), MOD) + int(s)) % MOD
            digits += len(s)
        return result, digits

    def _compute_repeat(self, n, val, length):
        # Concatenate 'val' n times
        result = 0
        for _ in range(n):
            result = (result * pow(10, length, MOD) + val) % MOD
        return result, length * n

def solution(s):
    parser = Parser(s)
    result, length = parser.parse_expr()
    return str(result)

