    params = lines[0].split()
    n, a, b = int(params[0]), int(params[1]), int(params[2])
    arr = list(map(int, lines[1].split()))

    def find_prime_factors(x):
        primes = set()
        d = 2
        while d * d <= x:
            if x % d == 0:
                primes.add(d)
                while x % d == 0:
                    x //= d
            d += 1
        if x > 1:
            primes.add(x)
        return primes

    candidates = set()
    for x in arr:
        candidates.update(find_prime_factors(x))

    # Generate more candidates from nearby values
    for x in arr:
        for offset in [-1, 1]:
            val = x + offset
            if val <= 0:
                continue
            candidates.update(find_prime_factors(val))

    def get_cost(arr_sub, g, a, b):
        n = len(arr_sub)
        bad = [i for i in range(n) if arr_sub[i] % g != 0]

        if not bad:
            return 0

        first_bad = bad[0]
        last_bad = bad[-1]
        num_bad = len(bad)

        # Option 1: modify all bad elements
        modify_cost = num_bad * b

        if num_bad <= 1:
            return min(modify_cost, a)

        # Option 2: remove subsegment from first_bad to last_bad
        subsegment_len = last_bad - first_bad + 1

        # Cannot remove entire array (m < n means at least 1 element remains)
        if subsegment_len >= n:
            return modify_cost

        remove_cost = subsegment_len * a
        return min(modify_cost, remove_cost)

    min_total_cost = float('inf')

    # Check each candidate prime
    for g in candidates:
        cost = get_cost(arr, g, a, b)
        min_total_cost = min(min_total_cost, cost)

    return str(min_total_cost)

