def get_paths_from_centroid(n, adj, centroid):
    # BFS to find all paths from centroid to every other node
    dist = [[-1] * (n + 1) for _ in range(n + 1)]
    parent = [0] * (n + 1)

    q = deque([(centroid, 0)])
    parent[centroid] = -1
    dist[centroid][centroid] = 0

    while q:
        u, d = q.popleft()
        for v in adj[u]:
            if parent[v] != u and dist[u][v] == -1:
                parent[v] = u
                dist[u][v] = d + 1
                q.append((v, d + 1))

    return parent, dist

