def is_valid_set(teams_a, teams_b, is_fifth_set):
    """Check if a set with given scores is valid according to volleyball rules"""
    if teams_a < 0 or teams_b < 0:
        return False

    if is_fifth_set:
        min_points = 15
    else:
        min_points = 25

    winner = max(teams_a, teams_b)
    loser = min(teams_a, teams_b)

    # Must have reached at least the target and won by 2
    if winner < min_points:
        return False
    if winner <= loser + 1:
        return False

    return True

